# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEPKİME HIZINA ETKİ EDEN FAKTÖRLER (1): MADDE CİNSİ, DERİŞİM VE YÜZEY</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Tepkenlerin Cinsi</text>\n  <text x="40" y="103" font-size="10.5" font-weight="bold" fill="#1e40af">• En Hızlı: Zıt İyonlu Tepkimeler</text>\n  <text x="48" y="120" font-size="10" fill="#475569">Ag+(suda) + Cl-(suda) -&gt; AgCl(k)</text>\n  <text x="40" y="143" font-size="10.5" font-weight="bold" fill="#1e40af">• Orta Hızlı: Aynı İyonlu / Elektron</text>\n  <text x="48" y="160" font-size="10" fill="#475569">Fe2+ + MnO4- (Redoks tepkimeleri)</text>\n  <text x="40" y="183" font-size="10.5" font-weight="bold" fill="#1e40af">• En Yavaş: Çok Bağ Kırılan Nötr</text>\n  <text x="48" y="200" font-size="10" fill="#475569">Organik yanma (C3H8 + 5O2), paslanma</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Tepken Derişimi (M)</text>\n  <text x="262" y="105" font-size="10.5" fill="#334155">• Birim hacimdeki tanecik sayısı</text>\n  <text x="270" y="122" font-size="10.5" fill="#475569">arttıkça etkin çarpışma sayısı artar.</text>\n  <text x="262" y="148" font-size="10.5" fill="#334155">• Tepkime hızı artar; ancak</text>\n  <text x="270" y="165" font-size="10.5" font-weight="bold" fill="#166534">eşik enerjisi (Ea) ve hız sabiti (k)</text>\n  <text x="270" y="182" font-size="10.5" font-weight="bold" fill="#166534">DEĞİŞMEZ!</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Katı Temas Yüzeyi</text>\n  <text x="485" y="105" font-size="10.5" fill="#334155">• Heterojen tepkimelerde katının</text>\n  <text x="493" y="122" font-size="10.5" fill="#475569">toz haline getirilmesi yüzey</text>\n  <text x="493" y="139" font-size="10.5" fill="#475569">alanını büyütür.</text>\n  <text x="485" y="162" font-size="10.5" font-weight="bold" fill="#854d0e">• Hız: Toz Zn &gt; Şerit Zn &gt; Blok Zn</text>\n  <text x="485" y="185" font-size="10.5" fill="#475569">• Hız sabiti (k) artar, Ea değişmez.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SICAKLIĞIN VE KATALİZÖRÜN TEPKİME HIZINA ETKİSİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">4. Sıcaklık Artışı (T2 &gt; T1)</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Hem endotermik hem ekzotermik</text>\n  <text x="60" y="120" font-size="10.5" font-weight="bold" fill="#991b1b">TÜM tepkimelerin hızını artırır!</text>\n  <text x="50" y="143" font-size="11" fill="#334155">• Ortalama kinetik enerji ve tanecik hızı artar.</text>\n  <text x="50" y="165" font-size="11" fill="#334155">• Eşik enerjisini (Ea) aşan tanecik oranı</text>\n  <text x="60" y="182" font-size="10.5" fill="#475569">ve hız sabiti (k) büyür.</text>\n  <text x="50" y="205" font-size="11" font-weight="bold" fill="#b91c1c">• Eşik enerjisinin (Ea) sayısal değeri DEĞİŞMEZ!</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">5. Pozitif Katalizör (Enzim / Metal)</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Tepkimeye girip değişmeden çıkan ve</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">yeni, düşük enerjili yol açan maddedir.</text>\n  <text x="380" y="143" font-size="11" font-weight="bold" fill="#1e40af">• İleri (Ea,i) ve geri (Ea,g) aktifleşme</text>\n  <text x="390" y="160" font-size="10.5" font-weight="bold" fill="#1e40af">enerjilerini eşit miktarda DÜŞÜRÜR!</text>\n  <text x="380" y="183" font-size="11" fill="#334155">• Tepkime entalpisini (ΔH = Ea,i - Ea,g)</text>\n  <text x="390" y="200" font-size="10.5" fill="#475569">ve oluşan ürün miktarını DEĞİŞTİRMEZ.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">TANECİK SAYISI - KİNETİK ENERJİ VE POTANSİYEL ENERJİ DİYAGRAMLARI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#ffffff" stroke="#cbd5e1"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">Maxwell-Boltzmann Kinetik Enerji Dağılımı</text>\n  <line x1="45" y1="205" x2="320" y2="205" stroke="#334155" stroke-width="1.5"/>\n  <line x1="45" y1="205" x2="45" y2="80" stroke="#334155" stroke-width="1.5"/>\n  <path d="M 45 205 Q 100 75 160 155 T 300 202" fill="none" stroke="#2563eb" stroke-width="2.5"/>\n  <path d="M 45 205 Q 130 105 200 145 T 315 198" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <line x1="230" y1="85" x2="230" y2="205" stroke="#16a34a" stroke-width="2" stroke-dasharray="4,3"/>\n  <line x1="195" y1="85" x2="195" y2="205" stroke="#9333ea" stroke-width="2" stroke-dasharray="4,3"/>\n  <text x="110" y="102" font-size="10.5" font-weight="bold" fill="#2563eb">T1 (Düşük)</text>\n  <text x="165" y="122" font-size="10.5" font-weight="bold" fill="#dc2626">T2 (Yüksek)</text>\n  <text x="230" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#16a34a">Ea1</text>\n  <text x="195" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#9333ea">Ea2 (Katalizörlü)</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#ffffff" stroke="#cbd5e1"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">Potansiyel Enerji - Tepkime Koordinatı</text>\n  <line x1="385" y1="205" x2="655" y2="205" stroke="#334155" stroke-width="1.5"/>\n  <line x1="385" y1="205" x2="385" y2="80" stroke="#334155" stroke-width="1.5"/>\n  <path d="M 385 160 L 425 160 Q 485 60 545 185 L 635 185" fill="none" stroke="#475569" stroke-width="2.5"/>\n  <path d="M 425 160 Q 485 105 545 185" fill="none" stroke="#16a34a" stroke-width="2.5" stroke-dasharray="5,3"/>\n  <text x="485" y="92" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#475569">Katalizörsüz Tepe</text>\n  <text x="485" y="138" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#16a34a">Katalizörlü Tepe</text>\n  <text x="517" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">ΔH değişmez, sadece aktifleşme enerjisi düşer!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
